/**
 * Hand-written cases for the Tier 3 fence-repair eval (#6188 T4).
 *
 * Each case is one page whose facts or takes fence Tier 1 leaves with a
 * residual reason a model may clear (`short_row`, `no_header`,
 * `row_before_header`, `extra_cells`, `header_unmapped`). `body` is the
 * section as written; `expected` is the whole section after a correct
 * repair, written by hand (the canonical header and separator, then every
 * row). Tokens: {FB}/{FE} facts markers, {TB}/{TE} takes markers, {FH}/{FS}
 * the canonical narrow facts header and separator, {FW}/{FWS} the wide
 * facts ones, {TH}/{TS} the narrow takes ones and {TW}/{TWS} the wide takes ones.
 *
 * Sets:
 * - `repairable`: a correct repair exists and passes every production gate
 *   (the oracle test proves it).
 * - `adversarial`: the only correct outcome is to stay held.
 *   `ambiguous` cases have two readings and the gates cannot tell them apart,
 *   so only the model can hold (`probe` is a plausible wrong guess the gates
 *   accept). `unrecoverable` cases lack a required value, so any repair must
 *   invent one and the gates reject it (`probe` is such a repair).
 *   `split_claim` cases have a claim cut in two by an unescaped pipe; the
 *   claim cannot be rejoined (gate b), so a repair can only keep it cut.
 * - `gate_limited`: a person would repair it, but the gates forbid the
 *   correct table (`expected` is that table; the oracle test proves the
 *   gates reject it). Diagnostic only.
 *
 * Names are placeholders only (alice-example, acme-example, fund-a, ...).
 */

export type CaseSet = 'repairable' | 'adversarial' | 'gate_limited';
export type CaseClass = 'short_row_trailing' | 'short_row_gap' | 'no_header' | 'row_before_header' | 'extra_cells' | 'header_unmapped' | 'mixed';

export interface Case {
  id: string;
  set: CaseSet;
  adversarial?: 'ambiguous' | 'unrecoverable' | 'split_claim';
  cls: CaseClass;
  kind: 'facts' | 'takes' | 'both';
  section?: 'body' | 'timeline';
  vis?: 'private' | 'world';
  tags: string[];
  note: string;
  body: string[];
  expected: string[] | null;
  /** Adversarial only: a whole answer a model might return for the sent rows (header, separator, rows). */
  probe?: string[];
}

